function validate(input) {
  for (const [index, spec] of input.entries()) {
    const name = `promise${index + 1}`;
    if (!spec || typeof spec !== 'object' || Array.isArray(spec)) return `${name} must be an object { t, value }.`;
    if (!Number.isInteger(spec.t) || spec.t < 0 || spec.t > 1000) return `${name}.t must be an integer from 0 to 1000.`;
    if (typeof spec.value !== 'number' || !Number.isFinite(spec.value) || Math.abs(spec.value) > 1e9) return `${name}.value must be a number from -10^9 to 10^9.`;
  }
  return null;
}

