function adapt(input, solve, kit) {
  const delayed = (spec, name) => new Promise((resolve) => setTimeout(() => {
    kit.trace(`${name} resolves with ${spec.value}`);
    resolve(spec.value);
  }, spec.t));
  const [spec1, spec2] = input;
  kit.trace('addTwoPromises(promise1, promise2) is called');
  const result = solve(delayed(spec1, 'promise1'), delayed(spec2, 'promise2'));
  if (!result || typeof result.then !== 'function') throw new Error('addTwoPromises must return a promise.');
  return result.then((sum) => {
    kit.trace(`The returned promise resolves with ${sum}`);
    if (typeof sum !== 'number') throw new Error('The returned promise must resolve with a number.');
    return sum;
  });
}

