function generate(rand, size) {
  const make = () => {
    const t = Math.floor(rand() * (size === 'small' ? 80 : 1001));
    const roll = rand();
    let value;
    if (size === 'large') value = Math.floor(rand() * 2000000001) - 1000000000;
    else if (roll < 0.15) value = 0;
    else if (roll < 0.3) value = (Math.floor(rand() * 41) - 20) / 4;
    else value = Math.floor(rand() * 41) - 20;
    return { t, value };
  };
  return [make(), make()];
}
